"""Редактор бирок CAM. Закройте программу, положите файл рядом с app.py."""
import ast,base64,hashlib,json,os,tempfile,zlib
from pathlib import Path
from datetime import datetime
DATA=(
 ''
 ''
)
DIGEST='bf5e3bab4a75be97d65d26cca9ca6ac11b5ef75cbb431efee097c38e5b794d22'

def setup():
    folder=Path(__file__).resolve().parent;target=folder/'app.py'
    required=('app.py','label_design.py','labels_ui.py','labels_export.py','label_options.py','label_drilling.py','label_layout.py')
    missing=[n for n in required if not (folder/n).is_file()]
    if missing:raise ValueError('Положите установщик в рабочую папку CAM. Не найдены: '+', '.join(missing))
    raw=zlib.decompress(base64.b64decode(DATA,validate=True))
    if hashlib.sha256(raw).hexdigest()!=DIGEST:raise ValueError('Установщик скопирован не полностью')
    sources=json.loads(raw)
    if set(sources)!={'label_template_hooks.py','label_templates.py','label_template_ui.py','label_sheet_maps.py'}:raise ValueError('Неверный состав обновления')
    text=target.read_text(encoding='utf-8-sig');lines=text.splitlines(keepends=True);remove=set();count=0
    for n in ast.parse(text).body:
        known=isinstance(n,ast.Import) and len(n.names)==1 and n.names[0].name=='label_template_hooks' and n.names[0].asname is None
        call=isinstance(n,ast.Expr) and isinstance(n.value,ast.Call) and ast.unparse(n.value)=='label_template_hooks.install(Workbench)'
        if known or call:
            if lines[n.lineno-1][:n.col_offset].strip() or (lines[n.end_lineno-1][n.end_col_offset:].strip() and not lines[n.end_lineno-1][n.end_col_offset:].lstrip().startswith('#')):raise ValueError('Нестандартное подключение. Файлы не изменены.')
            remove.update(range(n.lineno-1,n.end_lineno));count+=int(call)
    if count==1 and all((folder/n).is_file() and (folder/n).read_bytes()==v.encode() for n,v in sources.items()):print('Редактор бирок уже установлен.');return
    text=''.join(s for i,s in enumerate(lines) if i not in remove);nodes=ast.parse(text).body
    starts=[n for n in nodes if isinstance(n,ast.If) and ast.unparse(n.test)=="__name__ == '__main__'"]
    if len(starts)!=1 or not any(isinstance(n,ast.ClassDef) and n.name=='Workbench' for n in nodes):raise ValueError('Не найдена точка подключения CAM')
    lines=text.splitlines(keepends=True);lines.insert(starts[0].lineno-1,'\nimport label_template_hooks\nlabel_template_hooks.install(Workbench)\n\n');sources['app.py']=''.join(lines)
    for n,v in sources.items():compile(v,n,'exec')
    files={folder/n:v.encode('utf-8-sig' if n=='app.py' else 'utf-8') for n,v in sources.items()};old={p:p.read_bytes() if p.exists() else None for p in files}
    backup=folder/('backup-label-editor-'+datetime.now().strftime('%Y%m%d-%H%M%S-%f'));backup.mkdir()
    for p,v in old.items():
        if v is not None:(backup/p.name).write_bytes(v)
    temps=[];written=[]
    try:
        for p,b in files.items():
            with tempfile.NamedTemporaryFile('wb',dir=folder,delete=False) as f:
                temp=Path(f.name);temps.append((p,temp));f.write(b);f.flush();os.fsync(f.fileno())
        for p,temp in temps:os.replace(temp,p);written.append(p)
    except Exception:
        for p in reversed(written):
            if old[p] is None:p.unlink(missing_ok=True)
            else:p.write_bytes(old[p])
        raise
    finally:
        for p,temp in temps:temp.unlink(missing_ok=True)
    print('Готово. Перезапустите CAM. Раскрой → Документы → Настроить бирку. Резервная копия:',backup.name)

if __name__=='__main__':
    try:setup()
    except Exception as exc:print('ОБНОВЛЕНИЕ НЕ УСТАНОВЛЕНО:',exc)
    input('Нажмите Enter для закрытия...')
